from dataclasses import dataclass
from typing import Union

@dataclass
class ConvErr:
    NegativeValue: bool = False
    Overflow: str = ""

def safeToU64(n: int) -> Union[int, ConvErr]:
    left = n
    right = 0

    if left < 0:
        if True:
            return ConvErr(NegativeValue=True)
    else:
        if True:
            if left > (2**64 - 1):
                return ConvErr(Overflow="Value too large for u64")
            else:
                return left

def test_case(value: int, description: str):
    result = safeToU64(value)
    if isinstance(result, ConvErr):
        if result.NegativeValue:
            print(f"{description}: NegativeValue error")
        else:
            print(f"{description}: Overflow error - {result.Overflow}")
    else:
        print(f"{description}: {result}")

def main():
    # Test case 1: Negative value
    test_case(-5, "Test 1 (negative)")

    # Test case 2: Zero value
    test_case(0, "Test 2 (zero)")

    # Test case 3: Maximum u64 value
    test_case(2**64 - 1, "Test 3 (max u64)")

    # Test case 4: Just above maximum u64
    test_case(2**64, "Test 4 (overflow)")

    # Test case 5: Positive value within range
    test_case(42, "Test 5 (positive within range)")

    # Additional edge cases
    test_case(1, "Test 6 (small positive)")
    test_case(-1, "Test 7 (negative one)")

if __name__ == "__main__":
    main()

