#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    bool NegativeValue;
    char Overflow[256];
} ConvErr;

typedef struct {
    bool is_ok;
    union {
        uint64_t ok;
        ConvErr err;
    } value;
} Result_u64_ConvErr;

Result_u64_ConvErr safeToU64(int64_t n) {
    Result_u64_ConvErr result;
    if (n < 0) {
        result.is_ok = false;
        result.value.err.NegativeValue = true;
        result.value.err.Overflow[0] = '\0';
        return result;
    } else {
        if (n > UINT64_MAX) {
            result.is_ok = false;
            result.value.err.NegativeValue = false;
            strcpy(result.value.err.Overflow, "Value exceeds u64 maximum");
            return result;
        } else {
            result.is_ok = true;
            result.value.ok = (uint64_t)n;
            return result;
        }
    }
}

void printResult(Result_u64_ConvErr r) {
    if (r.is_ok) {
        printf("Ok: %lu\n", r.value.ok);
    } else {
        printf("Err: NegativeValue=%s, Overflow='%s'\n",
               r.value.err.NegativeValue ? "true" : "false",
               r.value.err.Overflow);
    }
}

int main() {
    Result_u64_ConvErr r;

    r = safeToU64(0);
    printResult(r);

    r = safeToU64(42);
    printResult(r);

    r = safeToU64(-5);
    printResult(r);

    r = safeToU64(9223372036854775807LL);
    printResult(r);

    r = safeToU64(-9223372036854775808LL);
    printResult(r);

    return 0;
}

