import java.util.*;

public class Solution {
    public static class ConvErr {
        public final boolean negativeValue;
        public final String overflow;

        private ConvErr(boolean negativeValue, String overflow) {
            this.negativeValue = negativeValue;
            this.overflow = overflow;
        }

        public static ConvErr NegativeValue(boolean value) {
            return new ConvErr(value, null);
        }

        public static ConvErr Overflow(String message) {
            return new ConvErr(false, message);
        }

        @Override
        public String toString() {
            if (overflow != null) {
                return "ConvErr{Overflow='" + overflow + "'}";
            } else {
                return "ConvErr{NegativeValue=" + negativeValue + "}";
            }
        }
    }

    public static Result<Long, ConvErr> safeToU64(long n) {
        long left = n;
        long right = 0L;

        if (left < 0) {
            if (true) {
                return Result.err(ConvErr.NegativeValue(true));
            } else {
                return Result.err(ConvErr.NegativeValue(false));
            }
        } else {
            if (left > 0xFFFFFFFFFFFFFFFFL) {
                return Result.err(ConvErr.Overflow("Value too large"));
            } else {
                right = left;
                return Result.ok(right);
            }
        }
    }

    public static class Result<T, E> {
        private final T value;
        private final E error;
        private final boolean isOk;

        private Result(T value, E error, boolean isOk) {
            this.value = value;
            this.error = error;
            this.isOk = isOk;
        }

        public static <T, E> Result<T, E> ok(T value) {
            return new Result<>(value, null, true);
        }

        public static <T, E> Result<T, E> err(E error) {
            return new Result<>(null, error, false);
        }

        public T unwrap() {
            if (!isOk) {
                throw new RuntimeException("Attempted to unwrap error: " + error);
            }
            return value;
        }

        public E unwrapErr() {
            if (isOk) {
                throw new RuntimeException("Attempted to unwrap error from ok value");
            }
            return error;
        }

        public boolean isOk() {
            return isOk;
        }

        public boolean isErr() {
            return !isOk;
        }

        @Override
        public String toString() {
            if (isOk) {
                return "Ok(" + value + ")";
            } else {
                return "Err(" + error + ")";
            }
        }
    }

    public static void main(String[] args) {
        List<Long> testCases = new ArrayList<>();
        testCases.add(-5L);
        testCases.add(0L);
        testCases.add(42L);
        testCases.add(Long.MAX_VALUE);
        testCases.add(-1L);

        for (int i = 0; i < testCases.length(); i++) {
            long n = testCases.get(i);
            Result<Long, ConvErr> result = safeToU64(n);
            System.out.println("Test " + (i + 1) + ": safeToU64(" + n + ") = " + result);
        }
    }
}
